prog='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    out = [row[:] for row in grid]
    if not marks:
        return out
    r0 = min(r for r, c in marks)
    r1 = max(r for r, c in marks)
    c0 = min(c for r, c in marks)
    c1 = max(c for r, c in marks)
    # Lines supported by at least three markers are extended across the
    # full marker bounding box; original markers remain unchanged.
    for r in range(r0, r1 + 1):
        if sum(rr == r for rr, c in marks) >= 3:
            for c in range(c0, c1 + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    for c in range(c0, c1 + 1):
        if sum(cc == c for r, cc in marks) >= 3:
            for r in range(r0, r1 + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out
'''
